-- 极客智坊（内置供应商 geekai）系统模型目录种子（ADR-0017：S 类文件，随启动幂等重跑）
-- 数据来源：公开模型列表 API https://geekai.co/api/models（2026-05-19 抓取，共 666 条）
-- 架构：模型目录全量 + 家族级 match_rule；OpenAI 兼容走 openai/openai_image，个性参数由适配层处理
-- 模型广场：https://geekai.co/models  文档：https://docs.geekai.co/llms.txt
-- API Base：https://geekai.co/api/v1
-- 依赖：表由 V001__init.sql 建立；provider/type（geekai）由先跑的 S001__system_seed.sql 建立。
-- 所有 INSERT 使用 ON DUPLICATE KEY UPDATE，严格幂等。

SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE
    `display_name` = VALUES(`display_name`),
    `group_name` = VALUES(`group_name`),
    `sort_order` = VALUES(`sort_order`),
    `icon_url` = VALUES(`icon_url`),
    `api_base_url` = VALUES(`api_base_url`),
    `endpoint_type` = VALUES(`endpoint_type`),
    `model_types` = VALUES(`model_types`),
    `is_free` = VALUES(`is_free`),
    `supports_test` = VALUES(`supports_test`),
    `update_time` = CURRENT_TIMESTAMP;

-- 家族级协议规则（远程导入 / 元数据推断）；不按 model_code 穷举
ON DUPLICATE KEY UPDATE
    `normalized_name` = VALUES(`normalized_name`),
    `display_name_template` = VALUES(`display_name_template`),
    `group_name` = VALUES(`group_name`),
    `icon_url` = VALUES(`icon_url`),
    `api_base_url` = VALUES(`api_base_url`),
    `endpoint_type` = VALUES(`endpoint_type`),
    `request_schema_json` = VALUES(`request_schema_json`),
    `response_schema_json` = VALUES(`response_schema_json`),
    `dsl_schema_json` = VALUES(`dsl_schema_json`),
    `model_types` = VALUES(`model_types`),
    `is_free` = VALUES(`is_free`),
    `priority` = VALUES(`priority`),
    `update_time` = CURRENT_TIMESTAMP;

UPDATE `ai_system_llm_model_match_rule`
SET `native_family` = 'qwen3',
    `channel_profile` = 'aggregator_unified',
    `adapter_key` = 'geekai.openai_chat'
WHERE `provider_type_code` = 'geekai'
  AND `provider_code` = 'geekai'
  AND `match_type` = 'prefix'
  AND `pattern` IN ('qwen3-', 'qwen3.')
  AND (`deleted` IS NULL OR `deleted` = 0);

UPDATE `ai_system_llm_model_match_rule`
SET `native_family` = 'seedream',
    `channel_profile` = 'aggregator_native',
    `adapter_key` = 'seedream.openai_images'
WHERE `provider_type_code` = 'geekai'
  AND `provider_code` = 'geekai'
  AND `match_type` = 'prefix'
  AND `pattern` = 'doubao-seedream'
  AND (`deleted` IS NULL OR `deleted` = 0);

UPDATE `ai_system_llm_model_match_rule`
SET `native_family` = 'gpt',
    `channel_profile` = 'aggregator_unified',
    `adapter_key` = 'geekai.openai_chat'
WHERE `provider_type_code` = 'geekai'
  AND `provider_code` = 'geekai'
  AND `match_type` = 'prefix'
  AND `pattern` IN ('gpt-', 'o1', 'o3', 'o4-')
  AND (`deleted` IS NULL OR `deleted` = 0);

UPDATE `ai_system_llm_model_match_rule`
SET `native_family` = 'gpt_image',
    `channel_profile` = 'aggregator_unified',
    `adapter_key` = 'openai.images'
WHERE `provider_type_code` = 'geekai'
  AND `provider_code` = 'geekai'
  AND `match_type` = 'prefix'
  AND `pattern` IN ('gpt-image', 'dall-e')
  AND (`deleted` IS NULL OR `deleted` = 0);

-- 清理曾按 model_code 穷举的 exact 规则（若执行过旧版种子）
DELETE FROM `ai_system_llm_model_match_rule`
WHERE `provider_type_code` = 'geekai'
  AND `provider_code` = 'geekai'
  AND `match_type` = 'exact'
  AND `id` >= 900000000000003100
  AND `id` < 900000000000004000
  AND (`deleted` IS NULL OR `deleted` = 0);
